CREATE TYPE public.app_role AS ENUM ('admin','agent');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT 'مستخدم', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, PRIMARY KEY(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE POLICY roles_self ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(nullif(trim(NEW.raw_user_meta_data->>'display_name'),''),'مستخدم')); RETURN NEW; END $$;
CREATE TRIGGER gas_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.agents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE REFERENCES public.profiles(id), name text NOT NULL, area text NOT NULL, district text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.agents TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.agents TO authenticated; GRANT ALL ON public.agents TO service_role;
ALTER TABLE public.agents ENABLE ROW LEVEL SECURITY;
CREATE POLICY agents_read ON public.agents FOR SELECT USING(true);
CREATE POLICY agents_admin ON public.agents FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, created_at date NOT NULL DEFAULT current_date, total_cylinders integer NOT NULL CHECK(total_cylinders>0), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','archived')), closed_at date);
GRANT SELECT ON public.batches TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.batches TO authenticated; GRANT ALL ON public.batches TO service_role;
ALTER TABLE public.batches ENABLE ROW LEVEL SECURITY;
CREATE POLICY batches_read ON public.batches FOR SELECT USING(true);
CREATE POLICY batches_admin ON public.batches FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.agent_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES public.batches(id) ON DELETE CASCADE, agent_id uuid NOT NULL REFERENCES public.agents(id), quantity integer NOT NULL CHECK(quantity>0), UNIQUE(batch_id,agent_id));
GRANT SELECT ON public.agent_allocations TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.agent_allocations TO authenticated; GRANT ALL ON public.agent_allocations TO service_role;
ALTER TABLE public.agent_allocations ENABLE ROW LEVEL SECURITY;
CREATE POLICY allocations_read ON public.agent_allocations FOR SELECT USING(true);
CREATE POLICY allocations_admin ON public.agent_allocations FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.distributions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_id uuid NOT NULL REFERENCES public.agents(id), batch_id uuid NOT NULL REFERENCES public.batches(id) ON DELETE CASCADE, recipient_name text NOT NULL CHECK(length(trim(recipient_name))>0), quantity integer NOT NULL CHECK(quantity>0), date date NOT NULL DEFAULT current_date, time time NOT NULL DEFAULT localtime, status text NOT NULL DEFAULT 'approved' CHECK(status IN ('approved','pending')), citizen_id text);
GRANT SELECT,INSERT ON public.distributions TO authenticated; GRANT ALL ON public.distributions TO service_role;
ALTER TABLE public.distributions ENABLE ROW LEVEL SECURITY;
CREATE POLICY distributions_private_read ON public.distributions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.agents a WHERE a.id=agent_id AND a.user_id=auth.uid()));
CREATE POLICY distributions_agent_insert ON public.distributions FOR INSERT TO authenticated WITH CHECK(status='approved' AND public.has_role(auth.uid(),'agent') AND EXISTS(SELECT 1 FROM public.agents a WHERE a.id=agent_id AND a.user_id=auth.uid() AND a.active));
CREATE TABLE public.adjustments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_id uuid NOT NULL REFERENCES public.agents(id), batch_id uuid NOT NULL REFERENCES public.batches(id) ON DELETE CASCADE, amount integer NOT NULL CHECK(amount<>0), reason text NOT NULL CHECK(length(trim(reason))>0), date date NOT NULL DEFAULT current_date);
GRANT SELECT,INSERT ON public.adjustments TO authenticated; GRANT ALL ON public.adjustments TO service_role;
ALTER TABLE public.adjustments ENABLE ROW LEVEL SECURITY;
CREATE POLICY adjustments_read ON public.adjustments FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.agents a WHERE a.id=agent_id AND a.user_id=auth.uid()));
CREATE POLICY adjustments_admin ON public.adjustments FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.app_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), collect_citizen_id boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.app_settings TO anon; GRANT SELECT,INSERT,UPDATE ON public.app_settings TO authenticated; GRANT ALL ON public.app_settings TO service_role;
ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_read ON public.app_settings FOR SELECT USING(true);
CREATE POLICY settings_admin ON public.app_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.validate_distribution() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE received integer; delivered integer; adjusted integer; current_status text; BEGIN SELECT status INTO current_status FROM public.batches WHERE id=NEW.batch_id FOR UPDATE; IF current_status IS DISTINCT FROM 'open' THEN RAISE EXCEPTION 'الدفعة مغلقة'; END IF; SELECT quantity INTO received FROM public.agent_allocations WHERE batch_id=NEW.batch_id AND agent_id=NEW.agent_id; SELECT coalesce(sum(quantity),0) INTO delivered FROM public.distributions WHERE batch_id=NEW.batch_id AND agent_id=NEW.agent_id AND status='approved'; SELECT coalesce(sum(amount),0) INTO adjusted FROM public.adjustments WHERE batch_id=NEW.batch_id AND agent_id=NEW.agent_id; IF received IS NULL OR NEW.quantity>received-delivered+adjusted THEN RAISE EXCEPTION 'الكمية تتجاوز المتبقي'; END IF; IF NEW.citizen_id IS NOT NULL AND NOT coalesce((SELECT collect_citizen_id FROM public.app_settings WHERE id=true),false) THEN RAISE EXCEPTION 'جمع الهوية غير مفعل'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_delivery BEFORE INSERT ON public.distributions FOR EACH ROW EXECUTE FUNCTION public.validate_distribution();
CREATE FUNCTION public.gas_state() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE admin_access boolean := false; uid uuid := auth.uid(); BEGIN IF uid IS NOT NULL THEN SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=uid AND role='admin') INTO admin_access; END IF; RETURN jsonb_build_object('agents',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'area',area,'district',district,'active',active)) FROM public.agents),'[]'::jsonb),'batches',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'code',code,'createdAt',created_at,'totalCylinders',total_cylinders,'status',status,'closedAt',closed_at)) FROM public.batches),'[]'::jsonb),'allocations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'batchId',batch_id,'agentId',agent_id,'quantity',quantity)) FROM public.agent_allocations),'[]'::jsonb),'deliveries',coalesce((SELECT jsonb_agg(jsonb_build_object('id',d.id,'agentId',d.agent_id,'batchId',d.batch_id,'recipientName',d.recipient_name,'quantity',d.quantity,'date',d.date,'time',d.time,'status',d.status) || CASE WHEN admin_access OR EXISTS(SELECT 1 FROM public.agents a WHERE a.id=d.agent_id AND a.user_id=uid) THEN jsonb_build_object('citizenId',d.citizen_id) ELSE '{}'::jsonb END) FROM public.distributions d WHERE d.status='approved' OR admin_access OR EXISTS(SELECT 1 FROM public.agents a WHERE a.id=d.agent_id AND a.user_id=uid)),'[]'::jsonb),'adjustments',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'agentId',agent_id,'batchId',batch_id,'amount',amount,'reason',CASE WHEN admin_access THEN reason ELSE 'تسوية موثقة' END,'date',date)) FROM public.adjustments),'[]'::jsonb),'settings',jsonb_build_object('collectCitizenId',coalesce((SELECT collect_citizen_id FROM public.app_settings WHERE id=true),false))); END $$;
REVOKE ALL ON FUNCTION public.gas_state() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.gas_state() TO anon,authenticated;
CREATE FUNCTION public.create_gas_batch(batch_code text, allocations jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; total integer; item record; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'غير مصرح'; END IF; SELECT sum(value::integer) INTO total FROM jsonb_each_text(allocations) WHERE value::integer>0; IF total IS NULL OR total<=0 THEN RAISE EXCEPTION 'الحصص مطلوبة'; END IF; INSERT INTO public.batches(code,total_cylinders) VALUES(trim(batch_code),total) RETURNING id INTO bid; FOR item IN SELECT key,value FROM jsonb_each_text(allocations) WHERE value::integer>0 LOOP INSERT INTO public.agent_allocations(batch_id,agent_id,quantity) VALUES(bid,item.key::uuid,item.value::integer); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.create_gas_batch(text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_gas_batch(text,jsonb) TO authenticated;
CREATE FUNCTION public.delete_old_batch(batch_id uuid, confirmation text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'غير مصرح'; END IF; IF NOT EXISTS(SELECT 1 FROM public.batches b WHERE b.id=batch_id AND b.status='archived' AND b.code=confirmation) THEN RAISE EXCEPTION 'يجب أرشفة الدفعة وكتابة رمزها للتأكيد'; END IF; DELETE FROM public.batches b WHERE b.id=batch_id; END $$;
REVOKE ALL ON FUNCTION public.delete_old_batch(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.delete_old_batch(uuid,text) TO authenticated;
CREATE FUNCTION public.assign_gas_agent(agent_id uuid, account_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'غير مصرح'; END IF; UPDATE public.agents a SET user_id=account_id WHERE a.id=agent_id; IF NOT FOUND THEN RAISE EXCEPTION 'الوكيل غير موجود'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(account_id,'agent') ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.assign_gas_agent(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.assign_gas_agent(uuid,uuid) TO authenticated;
CREATE INDEX distributions_batch_agent ON public.distributions(batch_id,agent_id);
CREATE INDEX distributions_recipient ON public.distributions(recipient_name);